CREATE COLUMN TABLE "TEST_AP"."@PO_TERM_COND" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_Term" NCLOB MEMORY THRESHOLD 1000, "U_From" LONGDATE CS_LONGDATE, "U_To" LONGDATE CS_LONGDATE, "U_Active" NVARCHAR(10), "U_TernCode" NVARCHAR(1), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KPO_TERM_COND_NAME" ON "TEST_AP"."@PO_TERM_COND" ( "Name" ASC )